import sys


def greet(name):
    if name == "":
        return "Hello, stranger!"
    return f"Hello, {name}!"


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("usage: greet.py NAME", file=sys.stderr)
        sys.exit(2)

    result = greet(sys.argv[1])
    print(result)
    sys.exit(0)
